//! ♻️ Network cleanup retains every original partial and captured issuer through its last admitted allocation release.
use super::*;
impl<S:NetworkPath> NetworkPreparation<S>{
 pub(super)fn start_close(&mut self){self.closing=true;if let Some(c)=self.link_cursor.as_mut(){c.begin_close()}if let Some(c)=self.stage.as_mut(){c.begin_close()}if let Some(c)=self.output.as_mut(){c.begin_close()}if let Some(c)=self.inverse_cursor.as_mut(){c.begin_close()}}
 pub(super)fn close_quote(&self,b:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}let b=self.body.unwrap_or(b);if self.output.is_some(){return cursor_demand(&self.output,b)}if self.stage.is_some(){return cursor_demand(&self.stage,b)}if self.link_cursor.is_some(){return cursor_demand(&self.link_cursor,b)}if self.inverse_cursor.is_some(){return cursor_demand(&self.inverse_cursor,b)}if !self.retirement.is_empty()||self.decision.is_some(){return self.retirement.next_owner_demands::<EnergyModelDiff>(self.decision.is_some(),&None,b)}if self.branch.is_some(){return self.retirement.next_owner_demands::<SealedShared<Systems>>(true,&None,b)}if self.value.is_some()||self.old.is_some(){return self.retirement.next_owner_demands::<OptionalNetwork>(true,&None,b)}if self.pairs.is_some(){return self.retirement.next_owner_demands::<SealedShared<Vec<Pair>>>(true,&None,b)}if self.links.is_some(){return self.retirement.next_owner_demands::<SealedShared<Vec<u32>>>(true,&None,b)}if self.raw_pairs.is_some(){return self.retirement.next_owner_demands::<Vec<Pair>>(true,&None,b)}if self.inverse.is_some(){return self.retirement.next_owner_demands::<NetworkInverse>(true,&None,b)}if self.old_source.is_some(){return self.retirement.next_owner_demands::<RetainedCloneSource<OptionalNetwork>>(true,&None,b)}RetainedCloneBinding::close_demand(if self.authored.is_some(){&self.authored}else{&self.original},b)}
 pub(super)fn close_advance(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_quote(self.body.unwrap_or(g.maximum_copy_bytes))?;if self.empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()))}let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..g};if self.output.is_some(){return close_cursor(&mut self.output,g).map(RetainedCloneStep::Progress)}if self.stage.is_some(){return close_cursor(&mut self.stage,g).map(RetainedCloneStep::Progress)}if self.link_cursor.is_some(){return close_cursor(&mut self.link_cursor,g).map(RetainedCloneStep::Progress)}if self.inverse_cursor.is_some(){return close_cursor(&mut self.inverse_cursor,g).map(RetainedCloneStep::Progress)}if !self.retirement.is_empty(){return self.retirement.select(self.body.unwrap_or(g.maximum_copy_bytes))?.step(g)}
 macro_rules! retire{($($field:ident),*)=>{$(if let Some(step)=self.retirement.begin_granted(&mut self.$field,g)?{return Ok(RetainedCloneStep::Progress(step.progress()))})*}}retire!(decision,branch,value,old,pairs,links,raw_pairs,inverse,old_source);RetainedCloneBinding::close_one(if self.authored.is_some(){&mut self.authored}else{&mut self.original},g)}
 pub(super)fn empty(&self)->bool{self.closing&&self.output.is_none()&&self.stage.is_none()&&self.link_cursor.is_none()&&self.inverse_cursor.is_none()&&self.decision.is_none()&&self.branch.is_none()&&self.value.is_none()&&self.old.is_none()&&self.pairs.is_none()&&self.links.is_none()&&self.raw_pairs.is_none()&&self.inverse.is_none()&&self.old_source.is_none()&&self.retirement.is_empty()&&self.authored.is_none()&&self.original.is_none()}
}
impl<S:NetworkPath> Drop for NetworkPreparation<S>{fn drop(&mut self){let empty=self.empty();assert!(std::thread::panicking()||empty,"original network retains source, candidate, inverse or branch custody");if empty{unsafe{ManuallyDrop::drop(&mut self.decision);ManuallyDrop::drop(&mut self.branch);ManuallyDrop::drop(&mut self.value);ManuallyDrop::drop(&mut self.old);ManuallyDrop::drop(&mut self.pairs);ManuallyDrop::drop(&mut self.links);ManuallyDrop::drop(&mut self.raw_pairs);ManuallyDrop::drop(&mut self.inverse);ManuallyDrop::drop(&mut self.old_source)}}}}
